          lerp(currentViewport.minX, targetViewport.minX, t2),
          lerp(currentViewport.minY, targetViewport.minY, t2),
          lerp(currentViewport.width, targetViewport.width, t2),
          lerp(currentViewport.height, targetViewport.height, t2)
